<template><div v-loading="loading" class="native-designer"><section class="designer-palette"><template v-for="group in allComponents" :key="group.title"><h3>{{group.title}}</h3><div class="palette-grid"><button v-for="item in group.list" :key="item.typeId" :disabled="locked||busy" draggable="true" @dragstart="dragType=item.typeId" @click="add(item.typeId)">{{item.config.label}}</button></div></template></section><section class="designer-canvas" @dragover.prevent @drop.prevent="drop"><div class="designer-title"><strong>表单设计</strong><el-tag :type="dirty?'warning':'success'">{{dirty?'有未保存修改':'已保存'}}</el-tag><el-button :loading="busy" :disabled="locked" type="primary" @click="saveAll">保存</el-button></div><el-alert v-if="locked" type="warning" title="该表单曾经发布，核心题目已冻结。请复制为新问卷后修改，以保留既有答卷口径。" :closable="false"/><div class="designer-info" aria-label="问卷标题"><FormTinymce v-if="!loading" v-model:value="info.name" inline :disabled="locked" placeholder="问卷标题" @update:value="dirty=true"/></div><div class="designer-info"><FormTinymce v-if="!loading" v-model:value="info.description" inline :disabled="locked" placeholder="问卷描述" @update:value="dirty=true"/></div><el-empty v-if="!fields.length" description="点击左侧题型或拖到这里添加题目"/><article v-for="(field,i) in fields" :key="field.config.formId" class="question-card" :class="{selected:selected===i}" :draggable="!locked" @dragstart.stop="dragIndex=i;dragType=''" @dragover.prevent @drop.stop.prevent="dropAt(i)" @click="selected=i"><strong>{{i+1}}. {{text(field.config.label)}} <span v-if="field.config.required" style="color:#ef4444">*</span></strong><div class="field-preview"><QuestionField :item="field" :model-value="field.config.defaultValue" :form-key="formKey" disabled/></div><div class="question-tools"><el-button :disabled="locked||busy||i===0" @click.stop="move(i,-1)">上移</el-button><el-button :disabled="locked||busy||i===fields.length-1" @click.stop="move(i,1)">下移</el-button><el-button :disabled="locked||busy" @click.stop="copy(i)">复制</el-button><el-button :disabled="locked||busy" type="danger" plain @click.stop="remove(i)">删除</el-button></div></article></section><section class="designer-config"><h3>题目设置</h3><div v-if="active"><FieldSettings :item="active" :disabled="locked" @change="dirty=true"/><el-button type="primary" :loading="busy" :disabled="locked" @click="saveAll">保存设置</el-button><el-divider/><el-button :disabled="locked" @click="openAdvanced">高级配置（JSON）</el-button></div><el-empty v-else description="请选择题目"/></section><el-dialog v-model="advancedOpen" title="高级题目配置" width="700px"><p>编辑选项、矩阵、子表单、校验及其他题型属性，保存时保留题目标识。</p><el-input v-model="advancedJson" type="textarea" :rows="20"/><template #footer><el-button @click="advancedOpen=false">取消</el-button><el-button type="primary" @click="applyAdvanced">应用</el-button></template></el-dialog></div></template>
<script setup>
import {ref,reactive,computed,onMounted,onBeforeUnmount,watch,provide} from 'vue'
import {useRoute,onBeforeRouteLeave} from 'vue-router'
import {ElMessage,ElMessageBox} from 'element-plus'
import api from '@/api'
import QuestionField from './QuestionField.vue'
import FieldSettings from './FieldSettings.vue'
import FormTinymce from '@/components/tinymce/index.vue'
import {allComponents} from './config'
import {clone,createField,formItemConvertData,dbDataConvertForItemJson} from './schema'
defineProps({questionMode:Boolean})
const route=useRoute(),formKey=String(route.query.key||'')
const fields=ref([]),info=reactive({}),selected=ref(-1),loading=ref(false),busy=ref(false),dirty=ref(false),advancedOpen=ref(false),advancedJson=ref('')
provide('tdResolvedOptions',reactive({}))
let dragType='',dragIndex=-1
const active=computed(()=>fields.value[selected.value]),locked=computed(()=>Number(info.status)>=2),text=v=>String(v||'').replace(/<[^>]*>/g,'')
const defaultText=computed(()=>typeof active.value?.config.defaultValue==='object'?JSON.stringify(active.value.config.defaultValue):active.value?.config.defaultValue??'')
function setDefault(value){try{active.value.config.defaultValue=JSON.parse(value)}catch{active.value.config.defaultValue=value}dirty.value=true}
async function load(){loading.value=true;try{const [form,items]=await Promise.all([api.get(`/user/form/${formKey}`),api.get('/user/form/item/list',{params:{key:formKey}})]);Object.assign(info,form.data);fields.value=items.data.map(dbDataConvertForItemJson);selected.value=fields.value.length?0:-1;dirty.value=false}finally{loading.value=false}}
onMounted(load)
watch(fields,()=>{if(!loading.value)dirty.value=true},{deep:true,flush:'sync'})
async function add(type){if(locked.value||busy.value)return;busy.value=true;try{const item=createField(type),res=await api.post('/user/form/item/create',formItemConvertData(item,formKey));item.sort=res.data.sort;fields.value.push(item);selected.value=fields.value.length-1}catch{}finally{busy.value=false}}
async function saveAll(){if(locked.value||busy.value)return;busy.value=true;try{await api.post('/user/form/update',{formKey,name:info.name,description:info.description});for(const item of fields.value)await api.post('/user/form/item/update',formItemConvertData(item,formKey));dirty.value=false;ElMessage.success('已保存')}finally{busy.value=false}}
async function remove(i){await ElMessageBox.confirm('确定删除该题目？','删除题目',{type:'warning'});busy.value=true;try{await api.post('/user/form/item/delete',formItemConvertData(fields.value[i],formKey));fields.value.splice(i,1);selected.value=Math.min(i,fields.value.length-1)}finally{busy.value=false}}
async function copy(i){if(locked.value)return;const item=clone(fields.value[i]);item.config.formId=createField(item.typeId).config.formId;item.vModel=item.config.formId;delete item.dId;const res=await api.post('/user/form/item/create',formItemConvertData(item,formKey));item.sort=res.data.sort;fields.value.push(item);selected.value=fields.value.length-1}
async function reorder(from,to){if(locked.value||busy.value||from===to)return;busy.value=true;const prev=fields.value.slice();try{const [item]=fields.value.splice(from,1);fields.value.splice(to,0,item);const res=await api.post('/user/form/item/sort',{formKey,formItemId:item.config.formId,beforePosition:fields.value[to-1]?.sort,afterPosition:fields.value[to+1]?.sort});item.sort=res.data.sort;selected.value=to;if(res.data.refreshAll)await load()}catch{fields.value=prev}finally{busy.value=false}}
function move(i,d){return reorder(i,i+d)}
async function drop(){if(dragType)await add(dragType);dragType='';dragIndex=-1}
async function dropAt(i){if(dragType){await add(dragType);await reorder(fields.value.length-1,i)}else if(dragIndex>=0)await reorder(dragIndex,i);dragType='';dragIndex=-1}
function addOption(){const ops=active.value.config.options;const next=Math.max(0,...ops.map(x=>Number(x.value)||0))+1;ops.push({label:`选项${next}`,value:next});dirty.value=true}
function openAdvanced(){advancedJson.value=JSON.stringify(active.value,null,2);advancedOpen.value=true}
function applyAdvanced(){try{const value=JSON.parse(advancedJson.value);if(value.typeId!==active.value.typeId||value.config?.formId!==active.value.config.formId)throw new Error('不能修改题型标识和题目 ID');fields.value[selected.value]=value;dirty.value=true;advancedOpen.value=false}catch(e){ElMessage.error(e.message)}}
onBeforeRouteLeave(async()=>{if(!dirty.value)return true;try{await ElMessageBox.confirm('当前修改尚未保存，是否离开？','未保存修改',{type:'warning'});return true}catch{return false}})
const beforeUnload=e=>{if(dirty.value){e.preventDefault();e.returnValue=''}}
window.addEventListener('beforeunload',beforeUnload);onBeforeUnmount(()=>window.removeEventListener('beforeunload',beforeUnload))
</script>
